-- ============================================================
-- 移除模块接口关联 — 数据库升级
-- 内容: SC_M18_UNLINK_API 种子脚本 + RS_M18 A08(APITYPE=csharp)
-- 用途: 其他模块资产"移除"(只解关联,不删文件)
-- 日期: 2026-07-17
-- ============================================================

INSERT INTO tss_api_script (ID, SCRIPTCODE, SCRIPTNAME, SOURCECODE, VERSION, REMARK, ISDELETED)
SELECT 'as_m18_unlink_api', 'SC_M18_UNLINK_API', '移除模块接口关联', , 1, 'RS_M18 A08: 删除 moudleapi 关联行(不删资产)', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_api_script WHERE SCRIPTCODE='SC_M18_UNLINK_API');

SET @m18 = (SELECT ID FROM tss_moudle WHERE MODULECODE='RS_M18');
INSERT INTO tss_moudleapi (ID, MODULEID, APICODE, ACTIONCODE, APITYPE, PATHNAME, APINAME, SCRIPTCODE, ENTRYNUM)
SELECT 'ma_m18_a08', @m18, 'A08', 'unlinkAsset', 'csharp', 'MAIN', '移除接口关联', 'SC_M18_UNLINK_API', 8
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_moudleapi WHERE ID='ma_m18_a08');
